Method.Source:
/// <summary>
/// Maps dialog fields above to contract method
/// </summary>
public void postBuild()
{
    super();
    contract = this.dataContractObject() as METSalesOrderLoadPlanningAidContract;

    DialogField dateFromDialogField = this.bindInfo().getDialogField(contract, methodStr(METSalesOrderLoadPlanningAidContract, parmConfirmedShipDateFrom));
    DialogField dateToDialogField = this.bindInfo().getDialogField(contract, methodStr(METSalesOrderLoadPlanningAidContract, parmConfirmedShipDateTo));
    dateFromDialogField.fieldControl().mandatory(true);
    dateToDialogField.fieldControl().mandatory(true);  
}
